queries:
SELECT link_to_event, AVG(remaining) - (SELECT AVG(remaining) FROM budget WHERE remaining IS NOT NULL) AS difference
FROM budget
GROUP BY link_to_event
SELECT link_to_event, AVG(remaining) - (SELECT AVG(event_avg) FROM (SELECT AVG(remaining) AS event_avg FROM budget GROUP BY link_to_event)) AS difference FROM budget GROUP BY link_to_event
SELECT link_to_event FROM budget GROUP BY link_to_event;
SELECT link_to_event FROM budget WHERE link_to_event IS NOT NULL GROUP BY link_to_event;
SELECT link_to_event, AVG(spent) FROM budget GROUP BY link_to_event
